            modelBuilder.Entity("PadiPay.Models.Order", b =>
                {
                    b.Navigation("Deliveries");

                    b.Navigation("Dispute");

                    b.Navigation("Messages");

                    b.Navigation("Review");
                });
#pragma warning restore 612, 618
        }
    }
